(()=>{
'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),norm=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const categories=[['accueil','⌂','Accueil'],['personnages','♙','Personnages'],['arcs','◷','Arcs & chronologie'],['combats','⚔','Combats'],['mondes','◎','Mondes & lieux'],['artefacts','◇','Armes & artefacts'],['concepts','✧','Lois & pouvoirs'],['factions','◈','Factions & menaces'],['tomes','▤','Les dix tomes'],['favoris','☆','Mes favoris']];
const entries=SH_WIKI.entries,cat=SH_CATALOG,chapterIndex=new Map(cat.flatMap(b=>b.chapters.map(c=>[c.id,c]))),byId=new Map(entries.map(e=>[e.id,e]));
const descriptions={personnages:'Des êtres primordiaux aux vies humaines. Chaque dossier rassemble une synthèse, ses liens et les passages des tomes.',arcs:'Un parcours de lecture de la genèse au Doute, prolongé par les récits du spin-off.',combats:'Les duels du corpus, avec les passages du combat et les conclusions documentées.',mondes:'Plans, domaines, mondes conceptuels et lieux de la vie humaine.',artefacts:'Les armes et instruments qui donnent une forme aux concepts.',concepts:'Les lois, les méthodes et les pouvoirs qui structurent l’univers.',factions:'Groupes, gardiennes, anomalies et menaces rencontrés dans les tomes.',tomes:'1 259 chapitres à lire, rechercher et retrouver par page PDF.',favoris:'Tes fiches et tes chapitres marqués, conservés sur cet appareil.'};
const storage={read:(k,f)=>{try{return JSON.parse(localStorage.getItem('sh-'+k))??f}catch{return f}},write:(k,v)=>{try{localStorage.setItem('sh-'+k,JSON.stringify(v))}catch{}}};
let favorites=new Set(storage.read('favorites',[])),bookmarks=new Set(storage.read('bookmarks',[])),shown=24,sourceShown=40,section='accueil',group='Tous',tomeFilter=0,query='',activeEntry=null,activeChapter=null,searchJob=0,summaries=storage.read('summaries',true);
const pendingBooks=new Map();
function loadBook(n){if(window.SH_PRIVATE_CORPUS===false)return Promise.reject(new Error("Le texte intégral est disponible dans la version privée. Il est exclu de ce dépôt public."));if(SH_BOOKS[n])return Promise.resolve(SH_BOOKS[n]);if(pendingBooks.has(n))return pendingBooks.get(n);const p=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='data/tome-'+n+'.js';s.onload=()=>resolve(SH_BOOKS[n]);s.onerror=()=>{pendingBooks.delete(n);s.remove();reject(new Error('Impossible de charger le tome '+n));};document.head.append(s)});pendingBooks.set(n,p);return p;}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2600)}
function closeDialog(d){d.close();if(!$('#reader').open&&!$('#dossier').open)document.body.style.overflow='';}
function showDialog(d){d.showModal();document.body.style.overflow='hidden';}
function toggleFavorite(id){favorites.has(id)?favorites.delete(id):favorites.add(id);storage.write('favorites',[...favorites]);if(activeEntry)renderDossier(activeEntry);if(section==='favoris')render();toast(favorites.has(id)?'Fiche ajoutée aux favoris':'Fiche retirée des favoris')}
function refreshSummary(){const b=$('#spoiler');b.textContent=summaries?'Résumés affichés':'Résumés masqués';b.setAttribute('aria-pressed',summaries);}
if(storage.read('theme','dark')==='light')document.body.classList.add('light');refreshSummary();
$('#theme').onclick=()=>{document.body.classList.toggle('light');storage.write('theme',document.body.classList.contains('light')?'light':'dark')};
$('#spoiler').onclick=()=>{summaries=!summaries;storage.write('summaries',summaries);refreshSummary();render();if(activeEntry)renderDossier(activeEntry);toast(summaries?'Résumés et résultats visibles':'Résumés et résultats masqués ; noms des fiches visibles')};
$('#menu').onclick=()=>{const open=document.body.classList.toggle('menu-open');$('#menu').setAttribute('aria-expanded',open)};
$('#navigation').innerHTML=categories.map(([id,icon,label])=>`<a href="#${id}" data-nav="${id}"><b aria-hidden="true">${icon}</b><span>${label}</span>${entries.some(e=>e.category===id)?`<small>${entries.filter(e=>e.category===id).length}</small>`:''}</a>`).join('');
function matches(e,q=query){const text=norm([e.name,e.subtitle,e.summary,...e.aliases,e.group].join(' '));return norm(q).trim().split(/\s+/).every(w=>text.includes(w));}
function eligible(e){return (!tomeFilter||e.tomes.includes(tomeFilter))&&(group==='Tous'||e.group===group)}
function card(e){return `<button class="card" data-entry="${esc(e.id)}">${favorites.has(e.id)?'<span class="bookmark-mark">★</span>':''}<span class="sigil" aria-hidden="true">${esc(e.name[0])}</span><small>${esc(e.subtitle)}</small><h3>${esc(e.name)}</h3><p>${summaries?esc(e.summary.slice(0,150))+(e.summary.length>150?'…':''):'Résumé masqué · Ouvrir les références'}</p><span class="meta"><span>${e.chapters.length} chapitre${e.chapters.length>1?'s':''} · ${e.tomes.length} tome${e.tomes.length>1?'s':''}</span><span class="arrow">↗</span></span></button>`;}
function sectionHeading(t,s=''){return `<div class="section-heading"><h2>${esc(t)}</h2><span>${s}</span></div>`}
function bindEntries(root=$('#content')){root.querySelectorAll('[data-entry]').forEach(b=>b.onclick=()=>openDossier(b.dataset.entry));root.querySelectorAll('[data-chapter]').forEach(b=>b.onclick=()=>openChapter(b.dataset.chapter,Number(b.dataset.page)||0));root.querySelectorAll('[data-book]').forEach(b=>b.onclick=()=>openBook(Number(b.dataset.book)));}
function renderHome(){const featured=['arc-11','spin-off-2'].map(id=>byId.get(id)).filter(Boolean);const chars=['amado-shirogane','noesis-absoluta','rebecca-shirogane','nyxara-abyssgarde','orphea-aurora','cael-virelios'].map(id=>byId.get(id)).filter(Boolean);
$('#content').innerHTML=`<div class="stats"><div class="stat"><strong>10</strong><span>tomes réunis</span></div><div class="stat"><strong>${entries.length}</strong><span>dossiers sourcés</span></div><div class="stat"><strong>1 259</strong><span>chapitres indexés</span></div><div class="stat"><strong>8 791</strong><span>pages du corpus</span></div></div>${sectionHeading('Au cœur des conflits','Deux portes d’entrée')}<div class="feature-grid">${featured.map(e=>`<button class="feature" data-entry="${e.id}"><small>${esc(e.subtitle)}</small><span class="arrow">↗</span><h3>${esc(e.name)}</h3><p>${summaries?esc(e.summary):'Résumé masqué. Ouvrir les sources.'}</p></button>`).join('')}</div>${sectionHeading('Les visages de l’univers','<a class="text-button" href="#personnages">Tous les personnages ↗</a>')}<div class="grid">${chars.map(card).join('')}</div>${sectionHeading('La mémoire des dix tomes','<a class="text-button" href="#tomes">Ouvrir le lecteur ↗</a>')}<div class="book-grid">${cat.map(b=>bookCard(b)).join('')}</div><div class="note">Les fiches proposent une synthèse et des références vérifiables. Le lecteur conserve le texte intégral des chapitres : utilise la recherche pour retrouver aussi les détails qui ne font pas encore l’objet d’un dossier.</div>`;bindEntries();}
function bookCard(b){return `<button class="book" data-book="${b.id}"><span class="book-no">${String(b.id).padStart(2,'0')}</span><span class="book-name">${b.id===10?'Spin-off':'Tome '+b.id}</span><small>${b.chapters.length} chapitres · ${b.pages} pages</small></button>`}
function buildFilters(){const groups=section==='accueil'||section==='tomes'||section==='favoris'?[]:[...new Set(entries.filter(e=>e.category===section&&e.group).map(e=>e.group))];$('#filters').innerHTML=groups.length?['Tous',...groups].map(g=>`<button class="chip ${g===group?'active':''}" data-group="${esc(g)}">${esc(g)}</button>`).join(''):'';if(section!=='accueil'&&section!=='favoris')$('#filters').innerHTML+=`<select id="tome-filter" class="chip" aria-label="Filtrer par tome"><option value="0">Tous les tomes</option>${cat.map(b=>`<option value="${b.id}" ${b.id===tomeFilter?'selected':''}>${esc(b.name)}</option>`).join('')}</select>`;$('#filters').querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>{group=b.dataset.group;shown=24;render()});const f=$('#tome-filter');if(f)f.onchange=()=>{tomeFilter=Number(f.value);shown=24;sourceShown=40;render()};}
function chapterRow(c){return `<button class="chapter-row" data-chapter="${c.id}"><span><strong>${esc(c.title)}</strong><small>Tome ${c.tome} · pages ${c.start}–${c.end}${bookmarks.has(c.id)?' · ★ Marqué':''}</small></span><span>↗</span></button>`;}
function renderFavorites(){const es=entries.filter(e=>favorites.has(e.id)&&matches(e));const chapters=[...bookmarks].map(id=>chapterIndex.get(id)).filter(c=>c&&(!query||norm(c.title).includes(norm(query))));$('#content').innerHTML=es.length||chapters.length?`${sectionHeading('Fiches enregistrées',String(es.length))}<div class="grid">${es.map(card).join('')}</div>${sectionHeading('Chapitres marqués',String(chapters.length))}<div class="list">${chapters.map(chapterRow).join('')}</div>`:'<div class="empty"><strong>Un espace pour tes découvertes.</strong>Ouvre une fiche pour l’ajouter aux favoris, ou marque un chapitre dans le lecteur.</div>';bindEntries();}
function render(){const name=categories.find(c=>c[0]===section)?.[2]||'Archives';document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===section));$('#breadcrumb').textContent=name;$('#page-title').innerHTML=section==='accueil'?'Tout commence par<br><em>une Conscience.</em>':esc(name);$('#page-description').textContent=section==='accueil'?'Des premières formes au dernier doute. Explore les êtres, les lois et les conflits d’un univers qui apprend à exister.':descriptions[section];buildFilters();
if(section==='favoris'){renderFavorites();return}if(query.trim()){renderSearch();return}searchJob++;
if(section==='accueil'){renderHome();return}if(section==='tomes'){$('#content').innerHTML='<div class="book-grid">'+cat.filter(b=>!tomeFilter||b.id===tomeFilter).map(bookCard).join('')+'</div>';bindEntries();return}
const all=entries.filter(e=>e.category===section&&eligible(e));if(section==='arcs'){$('#content').innerHTML='<div class="note">Les noms et les limites des arcs ci-dessous sont des regroupements éditoriaux pour faciliter la lecture. Les chapitres et leurs références correspondent au corpus fourni.</div><div class="timeline">'+all.map(e=>`<button class="timeline-card" data-entry="${e.id}"><small>${esc(e.subtitle)} · ${e.chapters.length} chapitres</small><h3>${esc(e.name)}</h3><p>${summaries?esc(e.summary):'Résumé masqué.'}</p></button>`).join('')+'</div>';}else{$('#content').innerHTML=`<div class="result-summary">${all.length} dossier${all.length>1?'s':''}</div><div class="grid">${all.slice(0,shown).map(card).join('')}</div>${all.length>shown?'<button id="more" class="primary" style="margin-top:24px">Afficher plus de dossiers</button>':''}${!all.length?'<div class="empty">Aucun dossier avec ces filtres.</div>':''}`;const more=$('#more');if(more)more.onclick=()=>{shown+=24;render()};}bindEntries();}
async function renderSearch(){const job=++searchJob,q=query.trim(),words=norm(q).split(/\s+/),es=entries.filter(e=>(section==='accueil'||section==='tomes'||e.category===section)&&eligible(e)&&matches(e,q));$('#content').innerHTML=`<div class="result-summary">${es.length} fiche${es.length>1?'s':''} pour « ${esc(q)} »</div><div class="grid">${es.slice(0,shown).map(card).join('')}</div>${es.length>shown?'<button id="more-dossiers" class="primary" style="margin-top:20px">Plus de fiches</button>':''}${section==='accueil'||section==='tomes'?'<div class="section-heading"><h2>Dans le texte des tomes</h2></div><div id="full-results" class="loading"><span class="loader"></span>Recherche dans les dix tomes…</div>':''}`;bindEntries();const more=$('#more-dossiers');if(more)more.onclick=()=>{shown+=24;renderSearch()};if(section!=='accueil'&&section!=='tomes')return;
try{await Promise.all(cat.filter(b=>!tomeFilter||b.id===tomeFilter).map(b=>loadBook(b.id)));if(job!==searchJob)return;const hits=[];for(const b of cat){if(tomeFilter&&b.id!==tomeFilter)continue;for(const c of SH_BOOKS[b.id]){for(const p of c.pages){const n=norm(p.text);if(words.every(w=>n.includes(w))){const pos=n.indexOf(words[0]);hits.push({c,page:p.page,snippet:p.text.slice(Math.max(0,pos-100),pos+320)});}}}}$('#full-results').className='';$('#full-results').innerHTML=`<div class="result-summary">${hits.length} page${hits.length>1?'s':''} trouvée${hits.length>1?'s':''} · ${Math.min(hits.length,sourceShown)} affichée${Math.min(hits.length,sourceShown)>1?'s':''}</div>${hits.slice(0,sourceShown).map(h=>`<button class="result" data-chapter="${h.c.id}" data-page="${h.page}"><small>Tome ${h.c.tome} · page ${h.page}</small><p><strong>${esc(h.c.title)}</strong></p><p>${highlight(h.snippet,q)}</p></button>`).join('')}${hits.length>sourceShown?'<button id="more-source" class="primary" style="margin-top:20px">Afficher plus de passages</button>':''}${!hits.length?'<div class="empty">Aucun passage trouvé. Essaie un nom ou un terme plus court.</div>':''}`;bindEntries($('#full-results'));const m=$('#more-source');if(m)m.onclick=()=>{sourceShown+=40;renderSearch()};}catch(err){if(job===searchJob)$('#full-results').innerHTML=`<div class="note">${esc(err.message)}. Réessaie après avoir ouvert le tome.</div>`;}}
function highlight(text,q){const words=norm(q).trim().split(/\s+/).filter(Boolean),n=norm(text),ranges=[];for(const w of words){let p=0;while((p=n.indexOf(w,p))>=0){ranges.push([p,p+w.length]);p+=w.length}}ranges.sort((a,b)=>a[0]-b[0]);let out='',last=0;for(const [a,b] of ranges){if(a<last)continue;out+=esc(text.slice(last,a))+'<mark>'+esc(text.slice(a,b))+'</mark>';last=b}return out+esc(text.slice(last));}
function openDossier(id){const e=byId.get(id);if(!e)return;activeEntry=e;renderDossier(e);if(!$('#dossier').open)showDialog($('#dossier'));}
function renderDossier(e){const sources=e.sources.slice(0,6);$('#dossier-body').innerHTML=`<div class="dossier-heading"><span class="eyebrow">${esc(categories.find(c=>c[0]===e.category)?.[2]||e.category)}</span><h2>${esc(e.name)}</h2><p>${esc(e.subtitle)}</p><p class="abstract">${summaries?esc(e.summary):'Résumé masqué. Les références restent consultables.'}</p></div><div class="facts"><span>${e.chapters.length} chapitres liés</span><span>${e.tomes.map(n=>'T'+n).join(' · ')}</span>${e.group?`<span>${esc(e.group)}</span>`:''}</div><div class="dossier-actions"><button class="primary" id="first-appearance">Lire le premier passage ↗</button><button class="quiet" id="favorite">${favorites.has(e.id)?'★ Retirer des favoris':'☆ Ajouter aux favoris'}</button></div>${e.outcome&&summaries?`<div class="note"><strong>Résultat documenté</strong><br>${esc(e.outcome)}</div>`:''}${e.editorial?'<p class="source-note">Parcours de lecture éditorial. Les titres et les pages des chapitres constituent les références du récit.</p>':''}${e.links?.length?`<section class="dossier-section"><h3>Dans le même univers</h3><div class="relations">${e.links.map(l=>`<button class="chip" data-entry="${l.id}">${esc(l.name)} ↗</button>`).join('')}</div></section>`:''}${summaries?(e.facets||[]).map(f=>`<section class="dossier-section"><h3>${esc(f.name)}</h3>${f.sources.map(s=>`<div class="source"><div class="source-head"><button data-chapter="${s.chapter}" data-page="${s.page}">Tome ${s.tome} · page ${s.page} ↗</button></div><blockquote>${esc(s.quote)}</blockquote></div>`).join('')}</section>`).join(''):''}<section class="dossier-section"><h3>Les sources du dossier</h3><p class="source-note">Extraits des PDF. Ouvre la page pour replacer chaque passage dans son contexte.${e.aliases.length>1?' Alias recherchés : '+esc(e.aliases.join(', '))+'.':''}</p>${sources.map(s=>`<div class="source"><div class="source-head"><button data-chapter="${s.chapter}" data-page="${s.page}">Tome ${s.tome} · page ${s.page} ↗</button><small>Source</small></div><blockquote>${summaries?esc(s.quote):'Extrait masqué. Ouvrir la page source.'}</blockquote></div>`).join('')}</section><section class="dossier-section"><h3>Tous les chapitres liés</h3><input type="search" id="related-search" class="chip" style="width:100%;border-radius:5px;margin-bottom:16px" placeholder="Filtrer les chapitres de cette fiche…" aria-label="Rechercher les chapitres liés"><div class="list" id="related-list"></div></section>`;
$('#favorite').onclick=()=>toggleFavorite(e.id);$('#first-appearance').onclick=()=>openChapter(e.first);bindEntries($('#dossier-body'));let amount=40;const displayRelated=()=>{const q=norm($('#related-search').value);const ch=e.chapters.map(id=>chapterIndex.get(id)).filter(c=>c&&(!q||norm(c.title).includes(q)));$('#related-list').innerHTML=ch.slice(0,amount).map(chapterRow).join('')+(ch.length>amount?'<button class="quiet" id="more-related" style="margin-top:15px">Plus de chapitres</button>':'');bindEntries($('#related-list'));const m=$('#more-related');if(m)m.onclick=()=>{amount+=40;displayRelated()};};$('#related-search').oninput=()=>{amount=40;displayRelated()};displayRelated();}
function openBook(n){const b=cat.find(b=>b.id===n);activeEntry=null;$('#dossier-body').innerHTML=`<div class="dossier-heading"><span class="eyebrow">Le corpus intégral</span><h2>${esc(b.name)}</h2><p>${b.pages} pages · ${b.chapters.length} chapitres</p></div><input id="book-search" class="chip" style="width:100%;border-radius:5px;margin:18px 0" type="search" placeholder="Un titre ou un numéro de chapitre…" aria-label="Chercher un chapitre"><div id="book-list" class="list"></div>`;const filter=()=>{const q=norm($('#book-search').value);$('#book-list').innerHTML=b.chapters.filter(c=>!q||norm(c.title).includes(q)).map(chapterRow).join('');bindEntries($('#book-list'));};filter();$('#book-search').oninput=filter;if(!$('#dossier').open)showDialog($('#dossier'));}
async function openChapter(id,page=0){const meta=chapterIndex.get(id);if(!meta)return;activeChapter=meta;$('#reader-title').textContent='Tome '+meta.tome+' · '+meta.title;$('#reader-body').innerHTML='<div class="loading"><span class="loader"></span>Ouverture du chapitre…</div>';if(!$('#reader').open)showDialog($('#reader'));$('#reader-save').textContent=bookmarks.has(id)?'★ Marqué':'☆ Marquer';const chapters=cat.find(b=>b.id===meta.tome).chapters,idx=chapters.findIndex(c=>c.id===id);$('#previous').disabled=idx===0&&meta.tome===1;$('#next').disabled=idx===chapters.length-1&&meta.tome===10;$('#previous').onclick=()=>idx>0?openChapter(chapters[idx-1].id):openChapter(cat[meta.tome-2].chapters.at(-1).id);$('#next').onclick=()=>idx<chapters.length-1?openChapter(chapters[idx+1].id):openChapter(cat[meta.tome].chapters[0].id);
try{const book=await loadBook(meta.tome);if(activeChapter.id!==id)return;const c=book.find(c=>c.id===id);$('#reader-body').innerHTML=c.pages.map(p=>`<section class="pdf-page" id="pdf-page-${p.page}"><div class="page-number">Tome ${c.tome} · page PDF ${p.page}</div><div class="page-text">${query?highlight(p.text,query):esc(p.text)}</div></section>`).join('');$('#reader').scrollTop=0;if(page)setTimeout(()=>document.getElementById('pdf-page-'+page)?.scrollIntoView({block:'start'}),30);storage.write('lastChapter',id);}catch(err){$('#reader-body').innerHTML=`<div class="note">${esc(err.message)}</div>`;}}
$('#reader-save').onclick=()=>{if(!activeChapter)return;const id=activeChapter.id;bookmarks.has(id)?bookmarks.delete(id):bookmarks.add(id);storage.write('bookmarks',[...bookmarks]);$('#reader-save').textContent=bookmarks.has(id)?'★ Marqué':'☆ Marquer';toast(bookmarks.has(id)?'Chapitre marqué':'Marque retirée')};
$('#font-size').value=storage.read('fontSize',18);$('#reader-body').style.fontSize=$('#font-size').value+'px';$('#font-size').oninput=()=>{$('#reader-body').style.fontSize=$('#font-size').value+'px';storage.write('fontSize',Number($('#font-size').value))};
$('#reader-close').onclick=()=>closeDialog($('#reader'));$('#dossier .close').onclick=()=>{activeEntry=null;closeDialog($('#dossier'))};for(const d of [$('#dossier'),$('#reader')]){d.addEventListener('cancel',ev=>{ev.preventDefault();closeDialog(d)});d.addEventListener('click',ev=>{if(ev.target===d){const r=d.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)closeDialog(d)}});}
window.shiroganeBack=()=>{if($('#reader').open){closeDialog($('#reader'));return true}if($('#dossier').open){closeDialog($('#dossier'));return true}if(section!=='accueil'){location.hash='accueil';return true}return false};
$('#about').onclick=()=>{activeEntry=null;$('#dossier-body').innerHTML='<div class="dossier-heading"><span class="eyebrow">Les archives</span><h2>Une encyclopédie vérifiable.</h2><p class="abstract">'+esc(SH_WIKI.note)+'</p></div><div class="note">Les pages indiquées correspondent à la pagination des PDF fournis. Les 1 259 chapitres, bonus inclus, sont disponibles dans le lecteur. Les extraits peuvent conserver les retours à la ligne et les variantes orthographiques des fichiers originaux.</div><div class="note">L’APK contient le corpus et fonctionne hors connexion. Les favoris, les marques de lecture et les préférences restent sur cet appareil. Aucun classement de puissance n’est ajouté sans preuve dans le récit.</div><a class="text-button" href="https://github.com/axiomatik2026/Shirogane-universe/tree/main/wiki" target="_blank" rel="noopener">Consulter les sources du projet ↗</a>';if(!$('#dossier').open)showDialog($('#dossier'))};
let debounce;$('#search').oninput=()=>{clearTimeout(debounce);debounce=setTimeout(()=>{query=$('#search').value;shown=24;sourceShown=40;render()},300)};$('#search-form').onsubmit=ev=>{ev.preventDefault();clearTimeout(debounce);query=$('#search').value;shown=24;sourceShown=40;render()};
function route(){const requested=decodeURIComponent(location.hash.slice(1))||'accueil';const valid=categories.some(c=>c[0]===requested);section=valid?requested:'accueil';group='Tous';tomeFilter=0;shown=24;sourceShown=40;query='';$('#search').value='';document.body.classList.remove('menu-open');$('#menu').setAttribute('aria-expanded','false');render();window.scrollTo(0,0);if(requested.startsWith('fiche/'))openDossier(requested.slice(6));if(requested.startsWith('chapitre/'))openChapter(requested.slice(9));}window.addEventListener('hashchange',route);route();
if(location.protocol==='file:')$('#offline-label').textContent='Corpus intégré · Hors connexion';else if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').then(()=>{$('#offline-label').textContent='Archives disponibles en ligne';navigator.serviceWorker.addEventListener('message',e=>{if(e.data==='offline-ready')$('#offline-label').textContent='Corpus prêt hors connexion'})}).catch(()=>{});
// Exposed read-only helpers for deterministic content and UI checks.
window.SH_APP={loadBook,matches,openDossier,openChapter,openBook,get section(){return section},get entries(){return entries}};
})();
